
package at.fhtw.aiprojectcoach.dto;

import at.fhtw.aiprojectcoach.entity.Priority;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.util.List;

// Structured user story generated by Gemini
public record GeneratedUserStoryResponse(

        @NotBlank(message = "Title must not be empty")
        @Size(max = 200, message = "Title must be at most 200 characters")
        String title,

        @NotBlank(message = "User story must not be empty")
        @Size(max = 500, message = "User story must be at most 500 characters")
        String userStory,

        @NotEmpty(message = "Acceptance criteria must not be empty")
        @Size(min = 2, max = 6,
              message = "There must be between 2 and 6 acceptance criteria")
        List<@NotBlank(message = "Acceptance criterion must not be empty") String> acceptanceCriteria,

        @NotNull(message = "Priority must be set")
        Priority priority

) {
}
